/bin/bash -lc "node --input-type=module <<'JS'
import { readFileSync } from 'node:fs';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import assert from 'node:assert/strict';
const html = readFileSync('public/index.html', 'utf8');
new Function(html.match(/<script type=\"module\">([\\s\\S]*?)<\\/script>/)[1]);
const directory = await mkdtemp(join(tmpdir(), 'workboard-launch-'));
const child = spawn('npm', ['start'], { detached: true, env: { ...process.env, PORT: '18080', DB_PATH: join(directory, 'workboard.sqlite') }, stdio: 'ignore' });
try {
  let response;
  for (let attempt = 0; attempt < 100; attempt++) {
    try { response = await fetch('http://127.0.0.1:18080/health'); break; }
    catch { await new Promise(resolve => setTimeout(resolve, 30)); }
  }
  assert.equal(response.status, 200);
  assert.deepEqual(await response.json(), { status: 'ok' });
  console.log('npm start health check and browser script syntax passed');
} finally {
  const exited = new Promise(resolve => child.once('exit', resolve));
  process.kill(-child.pid, 'SIGTERM');
  await exited;
  await rm(directory, { recursive: true, force: true });
}
